const themes = {
  neo: {number:'02',name:'Neo',label:'Ideas in motion',tag:'Aero after dark',description:'A small animation studio. Deep indigo, subtle light, and a dark canvas where code and shapes take center stage.',aero:55,bg:'#191E29',accent:'#B5AFF2',surface:'#262D40',text:'#EAE8E3',radius:'12 px',font:'Segoe UI · sans serif',shadow:'Soft glow and selective neon edges',note:'The content sits on an open canvas. Navigation uses understated indigo glass, circular numbers, and short descriptions. Sage and soft glow highlight the current lesson, while a subtle outer border frames the navigation. Code panels and cards carry the Aero character: smooth glow gradients and neon edges that brighten where light falls, then fade into shadow. Headers use diffuse light rather than sharp reflection bands. The shapes share this material, with soft inner light and graduated mint, lilac, and coral outlines. Mint (#95EBD0) and lilac (#BDAAFF) accents highlight syntax and small interface details, keeping the overall atmosphere calm.'},
  old: {number:'04',name:'Old',label:'A classic in a new light',tag:'Prisma · Classic Aero',description:'A nod to the original Aero era. Translucent window frames, glass tabs, and glossy buttons in a soft lavender palette.',aero:90,bg:'#CDCDDF',accent:'#55598E',surface:'#F4F3FA',text:'#30334E',radius:'8 px',font:'Segoe UI · sans serif',shadow:'Double frame and a floating window shadow',note:'The character comes from window frames, tabs, and reflections. Reading surfaces stay clean and matte.'}
};
themes.neo.sage = "#8BBDA3";
themes.neo.coral = "#DF866B";
themes.old.sage = "#8BAF9B";
themes.old.coral = "#CD7F66";
let theme = document.body.dataset.theme === "old" ? "old" : "neo";
const app = document.querySelector('#app');
const icon = (name, size=18) => {
 const paths = {moon:'<path d="M20.5 13A9 9 0 0 1 11 3.5 9 9 0 1 0 20.5 13Z"/>',play:'<path d="m9 5 11 7-11 7z"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M15 8V4H4v11h4"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',check:'<path d="m5 12 4 4L19 6"/>',palette:'<circle cx="12" cy="12" r="9"/><circle cx="8" cy="9" r="1"/><circle cx="15" cy="8" r="1"/><circle cx="17" cy="14" r="1"/><path d="M7 16h4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',replay:'<path d="M4 5v6h6M4 11a8 8 0 1 1 1 7"/>',code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-14-2 18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>'};
 return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.book}</svg>`;
};
const mark = `<span class="brand-mark" aria-hidden="true"><i></i><b></b><em></em></span>`;
const brand = `<a class="brand" href="index.html">${mark}<span>Manim<span class="brand-sub">LEARNING IN MOTION</span></span></a>`;
const source = `from manim import *

class FirstScene(Scene):
    def construct(self):
        circle = Circle(color="#8BAF9B")
        circle.set_fill("#8BAF9B", opacity=0.25)
        square = Square(color="#8588BE")
        square.set_fill("#8588BE", opacity=0.25)

        self.play(Create(circle))
        self.wait(0.5)
        self.play(Transform(circle, square), run_time=2)
        self.wait()
`;
const escapeHtml = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
function highlight(s){return escapeHtml(s).replace(/("[^"\n]*"|\b(?:from|import|class|def)\b|\b(?:Scene|Circle|Square|Create|Transform|FirstScene)\b|\b(?:self)\b|\b\d+(?:\.\d+)?\b)/g,m=>`<span class="${m.startsWith('"')?'str':/^(from|import|class|def)$/.test(m)?'kw':m==='self'?'self':/^\d/.test(m)?'num':'fn'}">${m}</span>`);}
function designToolbar(){return `<div class="design-toolbar"><a href="index.html" class="design-label"><span data-current-theme>${themes[theme].name}</span> <span>· Style guide</span></a><div class="toolbar-actions"><div class="theme-picker" role="group" aria-label="Page theme"><button type="button" data-theme-option="neo" aria-pressed="${theme==='neo'}">${icon('moon',14)}<span>Neo</span></button><button type="button" data-theme-option="old" aria-pressed="${theme==='old'}">${icon('sun',14)}<span>Old</span></button></div><button class="style-trigger" data-open-guide aria-label="Open style guide">${icon('palette',16)}<span>Style guide</span></button></div></div>`;}
function sidebar(){return `<aside class="sidebar" id="course-menu"><div class="sidebar-title"><span>YOUR LEARNING PATH</span><span>01 — 04</span></div><nav aria-label="Lesson contents"><a href="#introduction" class="lesson-link active"><span class="lesson-no">01</span><span>Your first scene<small>One circle, endless possibilities</small></span></a><a href="#code" class="lesson-link"><span class="lesson-no">02</span><span>From code to canvas<small>Build it step by step</small></span></a><a href="#concepts" class="lesson-link"><span class="lesson-no">03</span><span>The building blocks<small>Scene, Mobject and Animation</small></span></a><a href="#practice" class="lesson-link"><span class="lesson-no">04</span><span>Your turn<small>A small experiment</small></span></a></nav><div class="course-note"><span class="note-orb">${icon('book',22)}</span><strong>One idea at a time.</strong><p>You do not need to know everything to start creating.</p><span class="course-line"></span><small>MANIM FUNDAMENTALS</small></div><a class="reference-link" href="https://docs.manim.community/en/stable/tutorials/quickstart.html" target="_blank" rel="noopener">Manim CE documentation ↗</a></aside>`;}
function hero(){return `<section class="lesson-hero" id="introduction"><div class="hero-text"><p class="eyebrow"><span class="chapter-dot"></span> THE START OF SOMETHING &nbsp; / &nbsp; LESSON 01</p><h1>It all starts<br>with <em>a shape.</em></h1><p>Turn a few lines of Python into an idea in motion.<br class="desktop"> Your first Manim animation starts here.</p><div class="hero-actions"><a class="primary-btn" href="#code">${icon('play',16)} Create my first scene</a><span class="read-time">8 min read <i>·</i> Beginner</span></div></div><div class="hero-art" aria-hidden="true"><div class="art-grid"></div><span class="hero-circle"></span><span class="hero-square"></span><svg class="hero-triangle" viewBox="0 0 110 100" aria-hidden="true"><defs><radialGradient id="logo-coral-fill" cx="28%" cy="15%" r="105%"><stop offset="0" stop-color="#FFC4A8" stop-opacity=".82"/><stop offset=".35" stop-color="#EE9B7B" stop-opacity=".64"/><stop offset=".75" stop-color="#C76C59" stop-opacity=".40"/><stop offset="1" stop-color="#DF8E71" stop-opacity=".52"/></radialGradient><linearGradient id="logo-coral-edge" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FFE1CE" stop-opacity=".95"/><stop offset=".25" stop-color="#FFB294" stop-opacity=".88"/><stop offset=".55" stop-color="#D88770" stop-opacity=".22"/><stop offset=".78" stop-color="#EFA082" stop-opacity=".30"/><stop offset="1" stop-color="#FFD1B8" stop-opacity=".85"/></linearGradient></defs><path d="M55 2 L108 98 L2 98 Z" fill="url(#logo-coral-fill)" stroke="url(#logo-coral-edge)" stroke-width="1.2" stroke-linejoin="round"/></svg></div></section>`;}
function codePanel(){return `<section class="code-panel" aria-labelledby="code-title"><div class="panel-bar"><span id="code-title">${icon('code',16)} first_scene.py</span><button data-copy="source" class="copy-btn" aria-label="Copy Python code">${icon('copy',14)} <span>Copy</span></button></div><pre tabindex="0" aria-label="Python code for the first scene"><code>${source.trimEnd().split('\n').map((s,i)=>`<span class="code-line"><span class="line-no" aria-hidden="true">${i+1}</span><span>${highlight(s)||' '}</span></span>`).join('')}</code></pre><div class="code-status"><span><i></i> Python · Manim CE</span><button data-download>${icon('download',13)} Download .py</button></div></section>`;}
function previewPanel(){return `<section class="preview-panel" aria-labelledby="preview-title"><div class="panel-bar"><span id="preview-title"><i class="live-dot"></i> Preview</span><span class="small-label">INTERACTIVE DEMO</span></div><div class="preview-stage"><div class="stage-grid"></div><div class="stage-axis axis-x"></div><div class="stage-axis axis-y"></div><div class="morph-shape"></div><span class="stage-tag">${icon('code',12)} <span id="stage-operation">Circle → Square</span></span><span class="axis-label">x</span><span class="axis-label y-label">y</span></div><div class="player-controls"><button class="play-button" data-play aria-label="Play animation">${icon('play',17)}</button><input id="timeline" type="range" min="0" max="1000" value="0" aria-label="Animation position"><span id="time-label">0.0 / 4.5 s</span><button class="reset-button" data-reset aria-label="Restart animation">${icon('replay',15)}</button></div><p class="demo-caption">Browser simulation · does not run Python</p></section>`;}
function guideContent(){const t=themes[theme];return `<p class="eyebrow">${t.tag}</p><h2>${t.name}<em>${t.label}</em></h2><p>${t.description}</p><h3>The palette</h3><div class="token-swatches">${[['Background',t.bg],['Accent',t.accent],['Surface',t.surface],['Text',t.text],['Sage',t.sage],['Coral',t.coral]].map(([label,color])=>`<button data-color="${color}" aria-label="Copy color ${label} ${color}"><i style="background:${color}"></i><strong>${label}</strong><code>${color}</code></button>`).join('')}</div><h3>Typography and materials</h3><dl><div><dt>Font families</dt><dd>${t.font}</dd></div><div><dt>Code</dt><dd>SFMono / Consolas · 10–12 px</dd></div><div><dt>Corner radii</dt><dd>${t.radius}</dd></div><div><dt>Shadows</dt><dd>${t.shadow}</dd></div><div><dt>Type scale</dt><dd>48 / 26 / 18 / 15 / 12 px</dd></div></dl><p class="design-note">${t.note}</p><button class="primary-btn" data-tokens>${icon('download',16)} Download CSS variables</button>`;}
function lesson(){const t=themes[theme];app.innerHTML=`<a class="skip-link" href="#main">Skip to content</a>${designToolbar()}<div class="site-shell"><header class="site-header">${brand}<nav class="header-nav" aria-label="Main navigation"><a href="#introduction" class="selected">Learn</a><a href="#code">Lab</a><a href="#practice">Practice</a></nav><span class="header-caption">Math you can see.</span><button class="menu-button" aria-expanded="false" aria-controls="course-menu">${icon('menu')}<span>Lesson</span></button></header><div class="window-caption"><span>◈ &nbsp; Manim — Learning notebook</span><span aria-hidden="true">─ &nbsp; □ &nbsp; ×</span></div><div class="lesson-layout">${sidebar()}<main id="main" class="lesson-main"><div class="breadcrumbs"><span>Learn</span><span>›</span><span>Fundamentals</span><span>›</span><strong>Your first scene</strong><span class="lesson-edition">MANIM COMMUNITY</span></div>${hero()}<section class="work-section" id="code"><div class="section-heading"><div><p class="eyebrow">01 / FROM CODE TO CANVAS</p><h2>A few lines. An idea in motion.</h2></div><span class="lesson-chip">${icon('code',14)} Python</span></div><p class="section-description">We create a circle and transform it into a square. Every line plays a part.</p><div class="lab-grid">${codePanel()}${previewPanel()}</div><div class="terminal"><span class="terminal-label">IN YOUR TERMINAL</span><code><span>$</span> manim -pql first_scene.py FirstScene</code><button data-copy="command" aria-label="Copy terminal command">${icon('copy',16)}</button></div><aside class="tip"><span class="tip-icon">i</span><p><strong>Pauses matter, too.</strong> <code>self.wait()</code> gives the scene a moment to breathe. Timing is part of your explanation.</p></aside></section><section id="concepts" class="concepts"><div class="section-heading"><div><p class="eyebrow">02 / THE BUILDING BLOCKS</p><h2>Three ideas to get started.</h2></div></div><div class="concept-grid"><article><span class="concept-symbol scene-symbol">▣</span><span class="concept-number">01</span><h3>The scene</h3><code>Scene</code><p>This is your stage. Inside <code>construct()</code>, you decide what appears and in what order.</p></article><article><span class="concept-symbol object-symbol">○</span><span class="concept-number">02</span><h3>The objects</h3><code>Mobject</code><p>The visual pieces: shapes, text, or formulas. Here, we use <code>Circle</code> and <code>Square</code>.</p></article><article><span class="concept-symbol animation-symbol">↗</span><span class="concept-number">03</span><h3>Motion</h3><code>Animation</code><p><code>self.play()</code> plays the action. <code>Transform</code> changes an object into another shape.</p></article></div></section><section class="practice" id="practice"><div class="practice-icon">✦</div><div><p class="eyebrow">03 / LEARN BY DOING</p><h2>What if it became a triangle?</h2><p>Replace <code>Square</code> with <code>Triangle</code> and try a <code>run_time</code> of 3 seconds. Before running it, picture the result.</p><details><summary>Show a hint <span>+</span></summary><div class="hint"><p>You can keep the variable name, but renaming it to <code>triangle</code> makes the code clearer. Update its use in <code>Transform</code> as well.</p><pre><code>triangle = Triangle(color="#CD7F66")
triangle.set_fill("#CD7F66", opacity=0.25)
self.play(Transform(circle, triangle), run_time=3)</code></pre></div></details></div><button class="complete-button" data-complete>${icon('check',16)}<span>Mark as complete</span></button></section><footer class="lesson-footer"><span>${mark} One shape. One idea. One step forward.</span><button data-open-guide data-footer-guide>Explore ${t.name} ${icon('arrow',15)}</button></footer></main></div></div><dialog class="style-dialog"><div class="dialog-top"><span data-guide-title>STYLE GUIDE / ${t.name.toUpperCase()}</span><button data-close-guide aria-label="Close style guide">${icon('close',20)}</button></div><div class="dialog-content">${guideContent()}</div></dialog><div class="toast" role="status" aria-live="polite"></div>`;setupInteractions();}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function toast(message){const el=document.querySelector('.toast');el.textContent=message;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),2600);}
async function copy(text){try{if(navigator.clipboard && window.isSecureContext){await navigator.clipboard.writeText(text);}else{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity=0;document.body.append(area);area.select();if(!document.execCommand('copy'))throw new Error('copy');area.remove();}toast('Copied to clipboard');}catch{toast('Could not copy. Select the text and copy it manually.');}}
function applyTheme(next, persist=true){
 if(!Object.prototype.hasOwnProperty.call(themes,next))next='neo';
 theme=next;
 const t=themes[theme];
 document.body.dataset.theme=theme;
 document.documentElement.style.colorScheme=theme==='old'?'light':'dark';
 document.querySelector('meta[name="theme-color"]').content=t.bg;
 document.title=`Manim · ${t.name} — Your first scene`;
 document.querySelector('[data-current-theme]').textContent=t.name;
 document.querySelectorAll('[data-theme-option]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.themeOption===theme)));
 document.querySelector('[data-guide-title]').textContent=`STYLE GUIDE / ${t.name.toUpperCase()}`;
 document.querySelector('.dialog-content').innerHTML=guideContent();
 document.querySelector('[data-footer-guide]').innerHTML=`Explore ${t.name} ${icon('arrow',15)}`;
 if(persist){try{localStorage.setItem('manim-appearance',theme);}catch{}}
}
function downloadThemeTokens(){
 const t=themes[theme];
 const colors={bg:t.bg,accent:t.accent,surface:t.surface,text:t.text,sage:t.sage,coral:t.coral};
 const material=theme==='old'?{'window-frame':'#ECEAFA70','window-border':'#8589B599',highlight:'#FFFFFF'}:{'neon-mint':'#95EBD0','neon-lilac':'#BDAAFF','glass-radius':'12px','glass-edge-lilac':'#CBBAFF','glass-edge-mint':'#A6F6D5','glass-edge-coral':'#F5AE96'};
 const type={radius:t.radius.replace(' ',''),'font-body':'"Segoe UI", sans-serif','font-heading':'"Segoe UI", sans-serif','font-code':'"SFMono-Regular", Consolas, monospace','text-sm':'12px','text-base':'15px','text-lg':'18px','heading-sm':'26px','heading-lg':'48px'};
 const tokens=Object.entries({...colors,...material,...type}).map(([key,value])=>`  --${key}: ${value};`).join('\n');
 download(`manim-${theme}-tokens.css`,`/* Manim · ${t.name} — ${t.tag} */\n:root {\n${tokens}\n}\n`,'text/css');
}
function setupInteractions(){
 const dialog=document.querySelector('dialog');let opener;
 document.querySelectorAll('[data-open-guide]').forEach(b=>b.addEventListener('click',()=>{opener=b;dialog.showModal();}));
 document.querySelector('[data-close-guide]').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
 document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',()=>copy(b.dataset.copy==='source'?source:'manim -pql first_scene.py FirstScene')));
 document.querySelector('[data-download]').addEventListener('click',()=>download('first_scene.py',source,'text/x-python'));
 dialog.addEventListener('click',event=>{const color=event.target.closest('[data-color]');if(color)copy(color.dataset.color);if(event.target.closest('[data-tokens]'))downloadThemeTokens();});
 document.querySelectorAll('[data-theme-option]').forEach(button=>button.addEventListener('click',()=>applyTheme(button.dataset.themeOption)));
 const menu=document.querySelector('.menu-button');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);document.querySelector('.sidebar').classList.toggle('mobile-open',open);});
 const legacySections={'#introduccion':'#introduction','#codigo':'#code','#conceptos':'#concepts','#practica':'#practice'};
 const lessonLinks=[...document.querySelectorAll('.lesson-link')];
 const selectLesson=hash=>{hash=legacySections[hash]||hash;const target=lessonLinks.some(a=>a.hash===hash)?hash:'#introduction';lessonLinks.forEach(a=>{const active=a.hash===target;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});};
 const syncSection=()=>{const legacy=legacySections[location.hash];if(legacy){try{history.replaceState(null,'',legacy);}catch{}document.getElementById(legacy.slice(1))?.scrollIntoView({behavior:'instant'});}selectLesson(legacy||location.hash);};
 syncSection();
 window.addEventListener('hashchange',syncSection);
 lessonLinks.forEach(a=>a.addEventListener('click',()=>{selectLesson(a.hash);document.querySelector('.sidebar').classList.remove('mobile-open');menu.setAttribute('aria-expanded','false');}));
 const complete=document.querySelector('[data-complete]');let completed=false;try{completed=localStorage.getItem('manim-first-lesson')==='true';}catch{}
 const setComplete=()=>{complete.classList.toggle('completed',completed);complete.setAttribute('aria-pressed',String(completed));complete.querySelector('span').textContent=completed?'Lesson completed':'Mark as complete';};setComplete();complete.addEventListener('click',()=>{completed=!completed;try{localStorage.setItem('manim-first-lesson',String(completed));}catch{}setComplete();toast(completed?'One more idea in motion!':'Lesson marked as incomplete');});
 const shape=document.querySelector('.morph-shape'), range=document.querySelector('#timeline'), play=document.querySelector('[data-play]');let progress=0,playing=false,startTime=0,raf;
 function draw(){const elapsed=progress*4.5;const creation=Math.min(1,elapsed);const x=Math.max(0,Math.min(1,(elapsed-1.5)/2));const eased=x*x*(3-2*x);shape.style.opacity=Math.max(.3,creation);shape.style.transform=`scale(${.85+.15*creation})`;shape.style.borderRadius=`${50*(1-eased)}%`;shape.style.borderColor=`rgb(${139-6*eased},${175-39*eased},${155+35*eased})`;shape.style.background=`rgba(${139-6*eased},${175-39*eased},${155+35*eased},.25)`;range.value=progress*1000;range.style.setProperty('--progress',`${progress*100}%`);document.querySelector('#time-label').textContent=`${elapsed.toFixed(1)} / 4.5 s`;document.querySelector('#stage-operation').textContent=elapsed<1?'Create(circle)':elapsed<1.5?'wait(0.5)':elapsed<3.5?'Transform(circle, square)':'wait()';}
 function pause(){playing=false;cancelAnimationFrame(raf);play.innerHTML=icon('play',17);play.setAttribute('aria-label','Play animation');}
 function tick(now){progress=Math.min(1,(now-startTime)/4500);draw();if(progress<1)raf=requestAnimationFrame(tick);else pause();}
 play.addEventListener('click',()=>{if(playing){pause();return;}if(progress>=1)progress=0;playing=true;startTime=performance.now()-progress*4500;play.innerHTML='<span aria-hidden="true">Ⅱ</span>';play.setAttribute('aria-label','Pause animation');raf=requestAnimationFrame(tick);});
 range.addEventListener('input',()=>{pause();progress=range.value/1000;draw();});document.querySelector('[data-reset]').addEventListener('click',()=>{pause();progress=0;draw();});draw();
}
lesson();
applyTheme(theme,false);
